package io.knowledgebrain.activity;
import java.util.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;
import io.knowledgebrain.contracts.content.v1.NoteChangedPayloadV1;
import io.knowledgebrain.contracts.content.daily.v1.DailyNoteChangedPayloadV1;
class NoteActivityTest extends ActivityFixtures {
 @Test void noteAndDailyUseSameCanonicalPathAndIndependentHistoricalFacts()throws Exception{var space=id();for(String kind:List.of("NOTE","DAILY_NOTE")){var wire=wire(kind,space);var e=ActivityEvent.decode(ActivityEvent.TOPICS.get(kind),wire);assertEquals("content",ActivityEvent.group(kind));assertEquals("/api/spaces/"+space+"/notes/"+e.aggregateId(),e.targetPath());assertTrue(ActivityEvent.target(e));assertNull(e.content());assertNull(e.planning());assertNull(e.roadmapId());ActivityEvent.transport(ActivityEvent.TOPICS.get(kind),wire,e.aggregateId().toString(),headers(e));if(kind.equals("NOTE")){assertNotNull(e.note().revisionId());assertEquals("Pinned Markdown\n",e.detail());assertEquals(e.detail().getBytes(StandardCharsets.UTF_8).length,e.note().markdownBytes());assertFalse(e.note().truncated());assertNull(e.note().journalDate());}else{assertNull(e.note().revisionId());assertEquals("1582-10-10",e.note().journalDate());assertEquals("Asia/Seoul",e.note().timeZone());assertTrue(e.detail().isEmpty());}}}
 @Test void unicodeExcerptNeverSplitsCodePointsAndRetainsOriginalWireByteLength()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE",id()));var p=NoteChangedPayloadV1.parseFrom(env.getPayload());String raw="x".repeat(8191)+"😀"+"tail";var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE"),env.toBuilder().setPayload(p.toBuilder().setMarkdown(raw).build().toByteString()).build().toByteArray());assertEquals("x".repeat(8191),e.detail());assertEquals(8199,e.note().markdownBytes());assertTrue(e.note().truncated());assertEquals("😀".repeat(2048),NoteActivity.excerpt("😀".repeat(2049)));assertEquals("한".repeat(2730),NoteActivity.excerpt("한".repeat(3000)));assertEquals("x".repeat(8192),NoteActivity.excerpt("x".repeat(8192)));}
 @Test void frozenNoteControlPolicyIsPreservedAndBodiesStayPlainText()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE",id()));var p=NoteChangedPayloadV1.parseFrom(env.getPayload());String raw="<img src=x onerror=alert(1)>\u0001\n\t";var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE"),env.toBuilder().setPayload(p.toBuilder().setTitle("Legacy\u0001").setMarkdown(raw).build().toByteString()).build().toByteArray());assertEquals(raw,e.detail());assertEquals("Legacy\u0001",e.title());for(var bad:List.of(p.toBuilder().setMarkdown("x".repeat(32769)),p.toBuilder().setMarkdown("\u0000"),p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setVersion(0),p.toBuilder().setVersion(2),p.toBuilder().setNoteId(id().toString()),p.toBuilder().setState("RETIRED"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE"),env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}}
 @Test void archivedDailyEventsKeepLiteralBindingInsteadOfComputingItFromChangeTime()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("DAILY_NOTE",id()));var p=DailyNoteChangedPayloadV1.parseFrom(env.getPayload());var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("DAILY_NOTE"),env.toBuilder().setPayload(p.toBuilder().setNoteVersion(3).setNoteState("RETIRED").build().toByteString()).build().toByteArray());assertEquals("RETIRED",e.state());assertEquals(3,e.sourceVersion());assertEquals("1582-10-10",e.note().journalDate());for(var bad:List.of(p.toBuilder().setJournalDate("2026-02-30"),p.toBuilder().setJournalDate("0000-01-01"),p.toBuilder().setTimezone("+09:00"),p.toBuilder().setNoteVersion(0),p.toBuilder().setNoteState("MERGED"),p.toBuilder().setVisibility("PUBLIC"))){assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(ActivityEvent.TOPICS.get("DAILY_NOTE"),env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}}
 @Test void oldStoredRowsWithoutNoteFieldStayReadable(){var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("QUESTION"),wire("QUESTION",id()));var json=tools.jackson.databind.json.JsonMapper.builder().build();var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(e);tree.remove("note");assertEquals(e,json.treeToValue(tree,ActivityEvent.class));}
 @Test void noteCursorCannotCrossSpaceOrDailyKind(){var space=id();var q=ActivityQuery.parse(space,ActivityQueryTest.params("kind","NOTE","timezone","UTC"));var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE"),wire("NOTE",space));var params=ActivityQueryTest.params("kind","NOTE","timezone","UTC","before",q.cursor(e));assertEquals(e.eventId(),ActivityQuery.parse(space,params).event());assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),params));params.put("kind",new String[]{"DAILY_NOTE"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(space,params));}
}
